import os, json, numpy as np

N = 26
TOLS = [1e-9, 3e-9, 5e-9, 1e-8]

def _load_saved_best():
    try:
        c = np.loadtxt('storage/noesis/latest_centers.txt')
        r = np.loadtxt('storage/noesis/latest_radii.txt')
        return np.array(c, float).reshape(N,2), np.array(r, float).reshape(N,)
    except Exception:
        return None, None

def _grid_plus_hole_seed(r0=0.1 - 1e-8, eps=1e-8):
    coords = [0.1,0.3,0.5,0.7,0.9]
    centers = [[x,y] for x in coords for y in coords]  # 25
    d = float(np.linalg.norm(np.array([0.2,0.2]) - np.array([0.1,0.1])))
    r_hole = d - r0 - eps
    return np.array(centers, float), np.array([r0]*25 + [r_hole], float)

def _boundary_slacks(c, r):
    x = c[:,0]; y = c[:,1]
    return x - r, 1.0 - x - r, y - r, 1.0 - y - r

def _pair_slacks(c, r):
    diff = c[:, None, :] - c[None, :, :]
    dist = np.sqrt(np.sum(diff**2, axis=2))
    return dist - (r[:, None] + r[None, :])

def _active_sets(c, r, tol):
    s_xL, s_xR, s_yB, s_yT = _boundary_slacks(c, r)
    sp = _pair_slacks(c, r)
    b = set()
    for i in range(N):
        if s_xL[i] <= tol: b.add((int(i), 'xL'))
        if s_xR[i] <= tol: b.add((int(i), 'xR'))
        if s_yB[i] <= tol: b.add((int(i), 'yB'))
        if s_yT[i] <= tol: b.add((int(i), 'yT'))
    p = set()
    for i in range(N):
        for j in range(i+1, N):
            if sp[i, j] <= tol:
                p.add((int(i), int(j)))
    return b, p

def _jacc(a, b):
    if not a and not b: return 1.0
    inter = len(a & b); uni = len(a | b)
    return inter / uni if uni > 0 else 1.0

def _serialize_pairs(s):
    return sorted([[i, j] for (i, j) in s], key=lambda x: (x[0], x[1]))

def construct_packing():
    c, r = _load_saved_best()
    if c is None:
        c, r = _grid_plus_hole_seed()

    # Compute active sets for the tolerance grid
    results = {}
    sets_b = {}
    sets_p = {}
    for t in TOLS:
        b, p = _active_sets(c, r, t)
        sets_b[t] = b
        sets_p[t] = p
        results[str(t)] = {
            'boundary_size': len(b),
            'pairs_size': len(p)
        }

    # Pairwise Jaccards and diffs between consecutive tolerances and extremes
    comparisons = {'boundary': {}, 'pairs': {}}
    for i in range(len(TOLS)-1):
        t1, t2 = TOLS[i], TOLS[i+1]
        jb = _jacc(sets_b[t1], sets_b[t2])
        jp = _jacc(sets_p[t1], sets_p[t2])
        comparisons['boundary'][f'{t1}->{t2}'] = {'jaccard': jb, 'added': len(sets_b[t2]-sets_b[t1]), 'removed': len(sets_b[t1]-sets_b[t2])}
        comparisons['pairs'][f'{t1}->{t2}'] = {'jaccard': jp, 'added': len(sets_p[t2]-sets_p[t1]), 'removed': len(sets_p[t1]-sets_p[t2])}
    # Extremes
    t_lo, t_hi = TOLS[0], TOLS[-1]
    comparisons['boundary'][f'{t_lo}<->{t_hi}'] = {'jaccard': _jacc(sets_b[t_lo], sets_b[t_hi])}
    comparisons['pairs'][f'{t_lo}<->{t_hi}'] = {'jaccard': _jacc(sets_p[t_lo], sets_p[t_hi])}

    out = {
        'tolerances': TOLS,
        'sizes': results,
        'comparisons': comparisons
    }
    try:
        os.makedirs('storage/noesis/exports', exist_ok=True)
        with open('storage/noesis/exports/self_stability_tolgrid.json', 'w') as f:
            json.dump(out, f, indent=2)
    except Exception:
        pass

    return c.astype(float), r.astype(float)
